<?php
declare(strict_types=1);

final class PatrimonyController
{
    public function index(): void
    {
        $user=require_auth();$db=Database::connection();$uid=(int)$user['id'];$data=PatrimonyService::overview($uid);$stmt=$db->prepare('SELECT id,name FROM accounts WHERE user_id=:user AND is_active=1 ORDER BY name');$stmt->execute(['user'=>$uid]);$accounts=$stmt->fetchAll();$stmt=$db->prepare("SELECT id,name FROM categories WHERE user_id=:user AND type='expense' AND is_active=1 ORDER BY name");$stmt->execute(['user'=>$uid]);$categories=$stmt->fetchAll();$stmt=$db->prepare('SELECT * FROM assets WHERE id=:id AND user_id=:user');$stmt->execute(['id'=>(int)($_GET['edit_asset']??0),'user'=>$uid]);$editAsset=$stmt->fetch()?:null;$stmt=$db->prepare('SELECT * FROM liabilities WHERE id=:id AND user_id=:user');$stmt->execute(['id'=>(int)($_GET['edit_liability']??0),'user'=>$uid]);$editLiability=$stmt->fetch()?:null;render('patrimony/index',['title'=>'Patrimônio e dívidas','assetsTypes'=>PatrimonyService::ASSET_TYPES,'liabilityTypes'=>PatrimonyService::LIABILITY_TYPES,'accountsForPayment'=>$accounts,'expenseCategories'=>$categories,'editAsset'=>$editAsset,'editLiability'=>$editLiability,'errors'=>$_SESSION['_errors']??[]]+$data);unset($_SESSION['_errors']);
    }
    public function saveAsset(): void
    {
        $user=require_auth();verify_csrf();$db=Database::connection();$uid=(int)$user['id'];$id=(int)($_POST['id']??0);$name=trim((string)($_POST['name']??''));$type=(string)($_POST['type']??'');$value=FinancialService::moneyToCents((string)($_POST['current_value']??''));$date=(string)($_POST['valuation_date']??'');$notes=trim((string)($_POST['notes']??''));$errors=[];if(mb_strlen($name)<2||mb_strlen($name)>100)$errors[]='Informe o nome do bem.';if(!isset(PatrimonyService::ASSET_TYPES[$type]))$errors[]='Selecione um tipo de bem.';if($value===null||$value<0)$errors[]='Informe um valor válido.';if(!FinancialService::validDate($date))$errors[]='Informe uma data de avaliação válida.';if(mb_strlen($notes)>500)$errors[]='As observações devem ter até 500 caracteres.';if($errors){$_SESSION['_errors']=$errors;redirect('/patrimony');}$now=gmdate('c');if($id)$db->prepare('UPDATE assets SET name=:name,type=:type,current_value=:value,valuation_date=:date,notes=:notes,updated_at=:at WHERE id=:id AND user_id=:user')->execute(['name'=>$name,'type'=>$type,'value'=>$value,'date'=>$date,'notes'=>$notes,'at'=>$now,'id'=>$id,'user'=>$uid]);else $db->prepare('INSERT INTO assets(user_id,name,type,current_value,valuation_date,notes,created_at,updated_at) VALUES(:user,:name,:type,:value,:date,:notes,:created,:updated)')->execute(['user'=>$uid,'name'=>$name,'type'=>$type,'value'=>$value,'date'=>$date,'notes'=>$notes,'created'=>$now,'updated'=>$now]);redirect('/patrimony');
    }
    public function saveLiability(): void
    {
        $user=require_auth();verify_csrf();$db=Database::connection();$uid=(int)$user['id'];$id=(int)($_POST['id']??0);$name=trim((string)($_POST['name']??''));$type=(string)($_POST['type']??'');$original=FinancialService::moneyToCents((string)($_POST['original_amount']??''));$remaining=FinancialService::moneyToCents((string)($_POST['remaining_amount']??''));$due=(string)($_POST['due_date']??'');$notes=trim((string)($_POST['notes']??''));$errors=[];if(mb_strlen($name)<2||mb_strlen($name)>100)$errors[]='Informe o nome da dívida.';if(!isset(PatrimonyService::LIABILITY_TYPES[$type]))$errors[]='Selecione um tipo de obrigação.';if($original===null||$remaining===null||$original<0||$remaining<0||$remaining>$original)$errors[]='Os valores da dívida são inválidos.';if($due!==''&&!FinancialService::validDate($due))$errors[]='Informe uma data de vencimento válida.';if(mb_strlen($notes)>500)$errors[]='As observações devem ter até 500 caracteres.';if($errors){$_SESSION['_errors']=$errors;redirect('/patrimony');}$now=gmdate('c');if($id)$db->prepare('UPDATE liabilities SET name=:name,type=:type,original_amount=:original,remaining_amount=:remaining,due_date=:due,notes=:notes,updated_at=:at WHERE id=:id AND user_id=:user')->execute(['name'=>$name,'type'=>$type,'original'=>$original,'remaining'=>$remaining,'due'=>$due?:null,'notes'=>$notes,'at'=>$now,'id'=>$id,'user'=>$uid]);else $db->prepare('INSERT INTO liabilities(user_id,name,type,original_amount,remaining_amount,due_date,notes,created_at,updated_at) VALUES(:user,:name,:type,:original,:remaining,:due,:notes,:created,:updated)')->execute(['user'=>$uid,'name'=>$name,'type'=>$type,'original'=>$original,'remaining'=>$remaining,'due'=>$due?:null,'notes'=>$notes,'created'=>$now,'updated'=>$now]);redirect('/patrimony');
    }
    public function payLiability(): void
    {
        $user=require_auth();verify_csrf();$db=Database::connection();$uid=(int)$user['id'];$id=(int)($_POST['id']??0);$amount=FinancialService::moneyToCents((string)($_POST['amount']??''));$account=(int)($_POST['account_id']??0);$category=(int)($_POST['category_id']??0);$date=(string)($_POST['payment_date']??'');$stmt=$db->prepare('SELECT * FROM liabilities WHERE id=:id AND user_id=:user AND is_active=1');$stmt->execute(['id'=>$id,'user'=>$uid]);$debt=$stmt->fetch();$errors=[];if(!$debt)$errors[]='Dívida não encontrada.';if($amount===null||$amount<=0||($debt&&$amount>(int)$debt['remaining_amount']))$errors[]='O pagamento precisa ser maior que zero e não pode exceder o saldo da dívida.';if(!FinancialService::validDate($date))$errors[]='Informe uma data válida.';$stmt=$db->prepare('SELECT id FROM accounts WHERE id=:id AND user_id=:user AND is_active=1');$stmt->execute(['id'=>$account,'user'=>$uid]);if(!$stmt->fetchColumn())$errors[]='Selecione uma conta ativa.';if($category){$stmt=$db->prepare("SELECT id FROM categories WHERE id=:id AND user_id=:user AND type='expense' AND is_active=1");$stmt->execute(['id'=>$category,'user'=>$uid]);if(!$stmt->fetchColumn())$errors[]='Selecione uma categoria de despesa válida.';}if($errors){$_SESSION['_errors']=$errors;redirect('/patrimony');}$db->beginTransaction();try{$now=gmdate('c');$db->prepare("INSERT INTO transactions(user_id,account_id,category_id,type,description,amount,transaction_date,status,notes,created_at,updated_at) VALUES(:user,:account,:category,'expense',:description,:amount,:date,'paid','Pagamento de passivo',:created,:updated)")->execute(['user'=>$uid,'account'=>$account,'category'=>$category?:null,'description'=>'Pagamento de dívida: '.$debt['name'],'amount'=>$amount,'date'=>$date,'created'=>$now,'updated'=>$now]);$remaining=(int)$debt['remaining_amount']-$amount;$db->prepare('UPDATE liabilities SET remaining_amount=:remaining,is_active=:active,updated_at=:at WHERE id=:id AND user_id=:user')->execute(['remaining'=>$remaining,'active'=>$remaining>0?1:0,'at'=>$now,'id'=>$id,'user'=>$uid]);$db->commit();}catch(Throwable $error){$db->rollBack();throw $error;}redirect('/patrimony');
    }
    public function toggleAsset(): void {$this->toggle('assets');}
    public function toggleLiability(): void {$this->toggle('liabilities');}
    private function toggle(string $table): void {$user=require_auth();verify_csrf();Database::connection()->prepare("UPDATE $table SET is_active=1-is_active,updated_at=:at WHERE id=:id AND user_id=:user")->execute(['at'=>gmdate('c'),'id'=>(int)($_POST['id']??0),'user'=>$user['id']]);redirect('/patrimony');}
}
